const DEMO = [
  {id:1,title:'Gaji bulanan',category:'Pekerjaan',wallet:'BCA',amount:2170000,type:'income',date:'2026-11-06',time:'09:14'},
  {id:2,title:'Belanja mingguan',category:'Belanja',wallet:'Tunai',amount:250000,type:'expense',date:'2026-11-06',time:'18:42'},
  {id:3,title:'Kopi dan makan siang',category:'Makanan',wallet:'GoPay',amount:20000,type:'expense',date:'2026-11-05',time:'12:26'},
  {id:4,title:'Freelance desain',category:'Pekerjaan',wallet:'BCA',amount:1250000,type:'income',date:'2026-11-04',time:'16:05'},
  {id:5,title:'Transportasi',category:'Transportasi',wallet:'GoPay',amount:20000,type:'expense',date:'2026-11-04',time:'08:17'},
];
const memoryStorage = {};
function readStorage(key){try{return window.localStorage.getItem(key)}catch{return memoryStorage[key]||null}}
function writeStorage(key,value){memoryStorage[key]=value;try{window.localStorage.setItem(key,value)}catch{}}
function parseStored(key,fallback){try{return JSON.parse(readStorage(key)||'null')||fallback}catch{return fallback}}
let tx = parseStored('arus-demo-tx',DEMO);
const wallets = parseStored('arus-demo-wallets',[{name:'Tunai',icon:'◉',openingBalance:1500000},{name:'BCA',icon:'▤',openingBalance:5000000},{name:'GoPay',icon:'◈',openingBalance:500000}]);
const previousDemoAmounts=[8500000,245000,68000,1250000,42000];
const hasUnchangedPreviousDemo=tx.length===5&&tx.every((item,index)=>item.id===index+1&&item.amount===previousDemoAmounts[index]);
if(hasUnchangedPreviousDemo&&wallets.length===3){tx=DEMO;const openings={Tunai:1500000,BCA:5000000,GoPay:500000};for(const wallet of wallets)if(openings[wallet.name]!==undefined)wallet.openingBalance=openings[wallet.name];writeStorage('arus-demo-tx',JSON.stringify(tx))}
for(const wallet of wallets){if(wallet.openingBalance===undefined){let net=0;for(const item of tx){if(item.date>dateKey(new Date()))continue;if(item.type==='income'&&item.wallet===wallet.name)net+=item.amount;else if(item.type==='expense'&&item.wallet===wallet.name)net-=item.amount;else if(item.type==='transfer'){if(item.wallet===wallet.name)net-=item.amount;if(item.toWallet===wallet.name)net+=item.amount}}wallet.openingBalance=(wallet.balance||0)-net}}
writeStorage('arus-demo-wallets',JSON.stringify(wallets));
const DEFAULT_CATEGORIES=[['income','Pekerjaan'],['income','Hadiah'],['income','Lainnya'],['expense','Makanan'],['expense','Belanja'],['expense','Transportasi'],['expense','Tagihan'],['expense','Lainnya']].map(([type,name],index)=>({id:`default-${index+1}`,type,name}));
let categories=parseStored('arus-demo-categories',DEFAULT_CATEGORIES);
let selectedCashflowDate=null; let page = location.hash.slice(1) || 'home'; let formType='expense'; let query=''; let typeFilter='all'; let transactionWalletFilter='all'; let transactionDateFilter='all'; let period='Bulan'; let reportAnchor=new Date(); let reportWallet='all'; let showBalance=true; let selectedTxId=null; let editingTxId=null; let categoryType='expense'; let categoryFormType='expense'; let editingCategoryId=null; let pendingCategoryId=null; let selectedWalletGroup=null;
const rp=n=>'Rp '+Math.abs(Number(n)||0).toLocaleString('id-ID');
const compactRp=n=>{const value=Number(n)||0,absolute=Math.abs(value);const suffix=absolute>=1000000?`${(absolute/1000000).toLocaleString('id-ID',{maximumFractionDigits:2})} jt`:absolute>=1000?`${(absolute/1000).toLocaleString('id-ID',{maximumFractionDigits:1})} rb`:absolute.toLocaleString('id-ID');return `${value<0?'−':''}Rp ${suffix}`};
const signedRp=n=>`${n<0?'−':''}${rp(n)}`;
const icon=(name)=>`<i class="fa-solid ${name}" aria-hidden="true"></i>`;
const TRANSACTION_ACTIONS=[{type:'income',icon:'fa-arrow-down',label:'Pemasukan',tone:'income'},{type:'expense',icon:'fa-arrow-up',label:'Pengeluaran',tone:'expense'},{type:'transfer',icon:'fa-right-left',label:'Transfer',tone:'transfer'}];
function transactionActionButtons(){return TRANSACTION_ACTIONS.map(item=>`<button class="sheet-action" data-action="new-${item.type}"><span class="tile ${item.tone}">${icon(item.icon)}</span>${item.label}</button>`).join('')}
const setPage=(p)=>{page=p;location.hash=p;render();window.scrollTo(0,0)};
const toast=(s)=>{let t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)};
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const sum=(kind)=>{const now=new Date();return tx.filter(x=>x.type===kind&&x.date<=dateKey(now)&&x.date.slice(0,7)===dateKey(now).slice(0,7)).reduce((a,b)=>a+b.amount,0)};
function walletBalance(wallet){return Number(wallet.openingBalance||0)+tx.filter(x=>x.date<=dateKey(new Date())).reduce((balance,item)=>{if(item.type==='income'&&item.wallet===wallet.name)return balance+item.amount;if(item.type==='expense'&&item.wallet===wallet.name)return balance-item.amount;if(item.type==='transfer'){if(item.wallet===wallet.name)return balance-item.amount;if(item.toWallet===wallet.name)return balance+item.amount}return balance},0)}
function categoriesOf(type){return categories.filter(category=>category.type===type)}
function categoryUsage(category){return tx.filter(item=>item.type===category.type&&item.category===category.name).length}
function reportRange(){const anchor=new Date(reportAnchor);if(period==='Tahun')return {start:`${anchor.getFullYear()}-01-01`,end:`${anchor.getFullYear()}-12-31`};if(period==='Bulan')return {start:dateKey(new Date(anchor.getFullYear(),anchor.getMonth(),1)),end:dateKey(new Date(anchor.getFullYear(),anchor.getMonth()+1,0))};const monday=new Date(anchor);monday.setDate(anchor.getDate()-((anchor.getDay()+6)%7));const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);return {start:dateKey(monday),end:dateKey(sunday)}}
function reportTransactions(){const range=reportRange();return tx.filter(x=>x.type!=='transfer'&&x.date<=dateKey(new Date())&&x.date>=range.start&&x.date<=range.end&&(reportWallet==='all'||x.wallet===reportWallet))}
function filteredTransactions(){const today=new Date(),todayKey=dateKey(today);let start=null;if(transactionDateFilter==='month')start=`${todayKey.slice(0,7)}-01`;else if(transactionDateFilter==='7'||transactionDateFilter==='30'){const days=Number(transactionDateFilter)-1;const from=new Date(today);from.setDate(today.getDate()-days);start=dateKey(from)}return tx.filter(item=>`${item.title} ${item.category||''} ${item.wallet} ${item.toWallet||''}`.toLowerCase().includes(query.toLowerCase())&&(typeFilter==='all'||item.type===typeFilter)&&(transactionWalletFilter==='all'||item.wallet===transactionWalletFilter||item.toWallet===transactionWalletFilter)&&(!start||(item.date>=start&&item.date<=todayKey)))}
function reportTotal(items,type){return items.filter(x=>x.type===type).reduce((n,x)=>n+x.amount,0)}
function formatRangeLabel(){const start=new Date(`${reportRange().start}T12:00:00`),end=new Date(`${reportRange().end}T12:00:00`);if(period==='Tahun')return String(start.getFullYear());if(period==='Bulan')return start.toLocaleDateString('id-ID',{month:'long',year:'numeric'});return `${start.getDate()}–${end.getDate()} ${end.toLocaleDateString('id-ID',{month:'short',year:'numeric'})}`}
function shiftReport(direction){if(period==='Tahun')reportAnchor.setFullYear(reportAnchor.getFullYear()+direction);else if(period==='Bulan')reportAnchor.setMonth(reportAnchor.getMonth()+direction,1);else reportAnchor.setDate(reportAnchor.getDate()+7*direction)}
function renderTopBar(title='Arus',back=false){const target=page==='wallet-form'?'wallets':page==='transaction-detail'?'transactions':page==='category-form'?'categories':page==='add'&&editingTxId!==null?'transaction-detail':'home';return `<header class="topbar">${back?`<button class="back" data-go="${target}" aria-label="Kembali">${icon('fa-arrow-left')}</button><span class="top-title">${title}</span><span style="width:40px"></span>`:`<div class="home-top-brand"><span class="home-monogram">AR</span><span class="home-top-copy"><span>Selamat datang,</span><strong>Ahmad Rizky</strong></span></div><button class="avatar home-settings" data-go="settings" aria-label="Pengaturan">${icon('fa-gear')}</button>`}</header>`}
function nav(active){return `<nav class="bottomnav" aria-label="Navigasi utama"><button class="navitem ${active==='home'?'active':''}" data-go="home" aria-label="Beranda" ${active==='home'?'aria-current="page"':''}><span class="navicon">${icon('fa-house')}</span><span class="navlabel">Beranda</span></button><button class="navitem ${active==='transactions'?'active':''}" data-go="transactions" aria-label="Transaksi" ${active==='transactions'?'aria-current="page"':''}><span class="navicon">${icon('fa-receipt')}</span><span class="navlabel">Transaksi</span></button><button class="nav-add" data-action="open-sheet" aria-label="Tambah transaksi">${icon('fa-plus')}</button><button class="navitem ${active==='report'?'active':''}" data-go="report" aria-label="Laporan" ${active==='report'?'aria-current="page"':''}><span class="navicon">${icon('fa-chart-column')}</span><span class="navlabel">Laporan</span></button><button class="navitem ${active==='settings'?'active':''}" data-go="settings" aria-label="Pengaturan" ${active==='settings'?'aria-current="page"':''}><span class="navicon">${icon('fa-gear')}</span><span class="navlabel">Pengaturan</span></button></nav>`}
function walletRows(list=wallets){return list.map(w=>`<div class="wallet-row"><div class="tile">${icon(w.name.toLowerCase().includes('tunai')?'fa-money-bill-wave':w.name.toLowerCase().includes('go')?'fa-mobile-screen-button':'fa-building-columns')}</div><div class="wallet-info"><div class="row-title">${escapeHtml(w.name)}</div></div><div class="row-amount" aria-label="Saldo ${escapeHtml(w.name)}: ${rp(walletBalance(w))}">${rp(walletBalance(w))}</div></div>`).join('')}
function transactionTimeLabel(item){return item.time||new Date(`${item.date}T12:00:00`).toLocaleDateString('id-ID',{day:'numeric',month:'short'})}
function txRows(items,compact=false){return items.map(x=>{const meta=x.type==='transfer'?`${escapeHtml(x.wallet)} → ${escapeHtml(x.toWallet)}`:`${escapeHtml(x.category||'Lainnya')} · ${escapeHtml(x.wallet)}`;const inlineTime=x.time||new Date(`${x.date}T12:00:00`).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});return `<button class="tx-row${compact?' tx-row-compact':''}" type="button" data-action="open-detail" data-tx-id="${x.id}" aria-label="Detail ${escapeHtml(x.title)}, ${rp(x.amount)}${x.time?`, pukul ${x.time}`:''}"><span class="tile tx-tile ${x.type}">${icon(x.type==='income'?'fa-arrow-down':x.type==='transfer'?'fa-right-left':'fa-arrow-up')}</span><span class="tx-info"><span class="row-title">${escapeHtml(x.title)}</span><span class="row-meta">${meta}${compact?` <span class="meta-separator">·</span> <time>${inlineTime}</time>`:''}</span>${compact?'':`<span class="row-time">${transactionTimeLabel(x)}</span>`}</span><span class="row-amount ${x.type==='income'?'positive':x.type==='transfer'?'':'negative'}"><span class="tx-sign">${x.type==='income'?'+':x.type==='transfer'?'':'−'}</span> ${rp(x.amount)}</span></button>`}).join('')}
function home(){
  const total=wallets.reduce((sum,wallet)=>sum+walletBalance(wallet),0);
  const recent=tx.slice().sort((a,b)=>`${b.date}T${b.time||'00:00'}`.localeCompare(`${a.date}T${a.time||'00:00'}`)).slice(0,3);
  const todayKey=dateKey(new Date());
  const monthIncome=sum('income');
  const monthExpense=sum('expense');
  const monthTransfers=tx.filter(item=>item.type==='transfer'&&item.date<=todayKey&&item.date.slice(0,7)===todayKey.slice(0,7)).length;
  const flowDifference=monthIncome-monthExpense;
  const chartDays=Array.from({length:7},(_,index)=>{const day=new Date();day.setHours(12,0,0,0);day.setDate(day.getDate()-6+index);const key=dateKey(day);const items=tx.filter(item=>item.date===key&&item.date<=todayKey&&item.type!=='transfer');return {key,label:day.toLocaleDateString('id-ID',{weekday:'short'}).replace('.',''),income:items.filter(item=>item.type==='income').reduce((total,item)=>total+item.amount,0),expense:items.filter(item=>item.type==='expense').reduce((total,item)=>total+item.amount,0)}});
  const chartPeak=Math.max(1,...chartDays.flatMap(day=>[day.income,day.expense]));
  const walletIcon=(name)=>name.toLowerCase().includes('tunai')?'fa-money-bill-wave':name.toLowerCase().includes('go')?'fa-mobile-screen-button':'fa-building-columns';
  return `${renderTopBar()}<main>
    <div class="stack">
      <section class="card balance-card">
        <div class="balance-top"><span class="balance-label">TOTAL SALDO AKTIF</span><button class="eye" data-action="toggle-balance" aria-label="${showBalance?'Sembunyikan saldo':'Tampilkan saldo'}">${icon(showBalance?'fa-eye':'fa-eye-slash')}</button></div>
        <div class="balance">${showBalance?rp(total):'Rp ••••••••'}</div>
        <div class="balance-footer"><span>${icon('fa-wallet')} Tersebar di ${wallets.length} dompet</span></div>
      </section>
      <section class="home-actions-panel" aria-label="Catat transaksi">
        <h2 class="home-actions-title">Catat transaksi</h2>
        <div class="home-actions-grid">${TRANSACTION_ACTIONS.map(item=>`<button class="home-action" data-action="new-${item.type}" aria-label="Catat ${item.label.toLowerCase()}"><span class="home-action-icon ${item.tone}">${icon(item.icon)}</span><span>${item.label}</span></button>`).join('')}</div>
      </section>
      <section class="home-wallet-section home-list-section">
        <div class="section-head"><h2 class="h2">Dompet & rekening</h2></div>
        <div class="wallet-grid" id="wallet-carousel" aria-label="Kategori dompet">${[['cash','Tunai','fa-money-bill-wave'],['ewallet','E-wallet','fa-mobile-screen-button'],['bank','Rekening','fa-building-columns']].map(([kind,label,walletIconName])=>{const group=wallets.filter(wallet=>wallet.kind===kind||(wallet.kind==null&&(kind==='cash'?wallet.name.toLowerCase().includes('tunai'):kind==='ewallet'?/gopay|ovo|dana|linkaja|shopeepay/i.test(wallet.name):!wallet.name.toLowerCase().includes('tunai')&&!/gopay|ovo|dana|linkaja|shopeepay/i.test(wallet.name))));const amount=group.reduce((total,wallet)=>total+walletBalance(wallet),0);return `<button class="wallet-card wallet-group-card" data-wallet-group="${kind}" aria-label="${label}, ${group.length} dompet"><span class="wallet-card-icon">${icon(walletIconName)}</span><span class="wallet-card-copy"><strong>${showBalance?rp(amount):'Rp ••••'}</strong><span class="wallet-card-name">${label}</span></span></button>`}).join('')}</div>
      </section>
      <section class="home-summary card">
        <div class="section-head"><h2 class="h2">Ringkasan Bulan Ini</h2></div>
        <div class="summary-columns">
          <div class="summary-cell"><span class="summary-label">${icon('fa-arrow-down')} Masuk</span><strong class="positive">${rp(monthIncome)}</strong></div>
          <div class="summary-cell"><span class="summary-label">${icon('fa-arrow-up')} Keluar</span><strong class="negative">${rp(monthExpense)}</strong></div>
          <div class="summary-cell net"><span class="summary-label">${icon('fa-scale-balanced')} Selisih</span><strong class="${flowDifference>=0?'positive':'negative'}">${signedRp(flowDifference)}</strong></div>
        </div>
        
      </section>
      <section class="home-cashflow card" aria-labelledby="home-cashflow-title">
        <div class="section-head"><div><h2 class="h2" id="home-cashflow-title">Arus Keuangan</h2><span class="cashflow-caption">Tren 7 hari terakhir</span></div><span class="cashflow-period">Minggu ini ${icon('fa-chevron-down')}</span></div>
        <div class="cashflow-chart" role="group" aria-label="Grafik pemasukan dan pengeluaran tujuh hari terakhir, tidak termasuk transfer">${chartDays.map(day=>`<button class="cashflow-day ${selectedCashflowDate===day.key?'selected':''}" type="button" data-action="select-cashflow-day" data-date="${day.key}" data-income="${day.income}" data-expense="${day.expense}" aria-pressed="${selectedCashflowDate===day.key}" aria-label="${day.label}, pemasukan ${rp(day.income)}, pengeluaran ${rp(day.expense)}"><span class="cashflow-bars"><span class="cashflow-bar income" style="height:${day.income?Math.max(4,day.income/chartPeak*100):0}%"></span><span class="cashflow-bar expense" style="height:${day.expense?Math.max(4,day.expense/chartPeak*100):0}%"></span></span><span class="cashflow-label">${day.label}</span></button>`).join('')}</div>
        <div class="cashflow-legend"><span><i class="cashflow-dot income"></i>Pemasukan</span><span><i class="cashflow-dot expense"></i>Pengeluaran</span></div>
        <div class="cashflow-detail" id="cashflow-detail" aria-live="polite" hidden></div>
      </section>
      <section class="home-list-section">
        <div class="section-head"><h2 class="h2">Transaksi terbaru</h2><button class="link" data-go="transactions">Lihat semua ${icon('fa-arrow-right')}</button></div>
        <div class="transaction-list home-recent">${recent.length?recent.map(item=>txRows([item],true)).join(''):`<div class="home-empty"><span class="home-empty-icon">${icon('fa-receipt')}</span><strong>Belum ada transaksi</strong><span>Catat pemasukan atau pengeluaran pertamamu.</span></div>`}</div>
      </section>
    </div>
  </main>${nav('home')}`
}
function transactionGroups(items){const groups=new Map();for(const item of [...items].sort((a,b)=>`${b.date}T${b.time||'00:00'}`.localeCompare(`${a.date}T${a.time||'00:00'}`))){const date=item.date;if(!groups.has(date))groups.set(date,[]);groups.get(date).push(item)}return [...groups].map(([date,rows])=>`<div class="date-label">${new Date(`${date}T12:00:00`).toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><div class="transaction-list">${txRows(rows)}</div>`).join('')}
function transactions(){const items=filteredTransactions();const dateOptions=[['all','Semua tanggal'],['month','Bulan ini'],['7','7 hari'],['30','30 hari']];return `${renderTopBar()}<main><div class="heading"><div><div class="eyebrow">Catatan uangmu</div><h1 class="h1">Transaksi</h1></div><button class="secondary" data-action="open-sheet">＋ Catat</button></div><div class="stack"><label class="search"><span class="search-icon">${icon('fa-magnifying-glass')}</span><input id="search" aria-label="Cari transaksi" placeholder="Cari transaksi" value="${escapeHtml(query)}"></label><div class="pill-row"><button class="pill ${typeFilter==='all'?'active':''}" data-action="filter-all">Semua</button><button class="pill ${typeFilter==='income'?'active':''}" data-action="filter-income">Pemasukan</button><button class="pill ${typeFilter==='expense'?'active':''}" data-action="filter-expense">Pengeluaran</button></div><label class="field filter-wallet"><span>Dompet</span><select class="control" id="transactionWallet"><option value="all" ${transactionWalletFilter==='all'?'selected':''}>Semua dompet</option>${wallets.map(w=>`<option value="${escapeHtml(w.name)}" ${transactionWalletFilter===w.name?'selected':''}>${escapeHtml(w.name)}</option>`).join('')}</select></label><div class="pill-row date-filters" aria-label="Rentang tanggal">${dateOptions.map(([value,label])=>`<button class="pill ${transactionDateFilter===value?'active':''}" data-action="date-filter" data-date-filter="${value}">${label}</button>`).join('')}</div><section class="card">${items.length?transactionGroups(items):`<div class="empty"><div class="empty-icon">${icon('fa-magnifying-glass')}</div><b>Transaksi tidak ditemukan</b><p>Coba kata kunci, dompet, atau rentang tanggal lain.</p></div>`}</section><div class="sub">Data contoh prototipe · interaksi disimpan di browser ini</div></div></main>${nav('transactions')}`}
function transactionDetail(){
  const item=tx.find(x=>x.id===selectedTxId);
  if(!item)return `${renderTopBar('Detail transaksi',true)}<main><section class="card empty"><div class="empty-icon">${icon('fa-circle-exclamation')}</div><b>Transaksi tidak ditemukan</b><p>Transaksi ini mungkin sudah dihapus.</p><button class="secondary" data-go="transactions">Kembali ke transaksi</button></section></main>`;
  const kind=item.type==='income'?'Pemasukan':item.type==='transfer'?'Transfer':'Pengeluaran';
  const sign=item.type==='income'?'+':item.type==='expense'?'−':'';
  const dateLabel=new Date(`${item.date}T12:00:00`).toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  const momentLabel=item.time?`${dateLabel} · ${item.time}`:dateLabel;
  return `${renderTopBar('Detail transaksi',true)}<main><div class="stack"><section class="card detail-hero"><span class="detail-icon ${item.type}">${icon(item.type==='income'?'fa-arrow-down':item.type==='transfer'?'fa-right-left':'fa-arrow-up')}</span><div class="detail-kind">${kind}</div><div class="detail-amount ${item.type==='income'?'positive':item.type==='expense'?'negative':''}">${sign}${rp(item.amount)}</div><div class="detail-date">${momentLabel}</div></section><section class="card detail-fields"><div class="detail-field"><span>Catatan</span><strong>${escapeHtml(item.note||item.title)}</strong></div><div class="detail-field"><span>${item.type==='transfer'?'Dari dompet':'Dompet'}</span><strong>${escapeHtml(item.wallet)}</strong></div>${item.type==='transfer'?`<div class="detail-field"><span>Ke dompet</span><strong>${escapeHtml(item.toWallet)}</strong></div>`:`<div class="detail-field"><span>Kategori</span><strong>${escapeHtml(item.category||'Lainnya')}</strong></div>`}</section><button class="primary full" data-action="edit-tx">${icon('fa-pen')} Edit transaksi</button><button class="danger-button full" data-action="confirm-delete">${icon('fa-trash-can')} Hapus transaksi</button></div></main>`
}
function report(){const entries=reportTransactions();const income=reportTotal(entries,'income'),expense=reportTotal(entries,'expense');const range=reportRange();const buckets=[];if(period==='Tahun'){for(let m=0;m<12;m++){const s=dateKey(new Date(reportAnchor.getFullYear(),m,1)),e=dateKey(new Date(reportAnchor.getFullYear(),m+1,0));buckets.push({label:new Date(reportAnchor.getFullYear(),m,1).toLocaleDateString('id-ID',{month:'short'}),start:s,end:e})}}else{let cursor=new Date(`${range.start}T12:00:00`),last=new Date(`${range.end}T12:00:00`);while(cursor<=last){let end=new Date(cursor);if(period==='Bulan'){end.setDate(cursor.getDate()+(6-((cursor.getDay()+6)%7)));if(end>last)end=last}else end=new Date(cursor);buckets.push({label:period==='Minggu'?cursor.toLocaleDateString('id-ID',{weekday:'short'}):`${cursor.getDate()}–${end.getDate()}`,start:dateKey(cursor),end:dateKey(end)});cursor=new Date(end);cursor.setDate(cursor.getDate()+1)}}const values=buckets.map(b=>({ ...b,income:reportTotal(entries.filter(x=>x.date>=b.start&&x.date<=b.end),'income'),expense:reportTotal(entries.filter(x=>x.date>=b.start&&x.date<=b.end),'expense')}));const peak=Math.max(0,...values.flatMap(x=>[x.income,x.expense]));return `${renderTopBar()}<main><div class="heading"><div><div class="eyebrow">Ringkasan arus uang</div><h1 class="h1">Laporan</h1></div></div><div class="stack"><div class="pill-row">${['Minggu','Bulan','Tahun'].map(p=>`<button class="pill ${period===p?'active':''}" data-period="${p}">${p}</button>`).join('')}</div><div class="period-control"><button class="period-arrow" data-action="period-prev" aria-label="Periode sebelumnya">${icon('fa-chevron-left')}</button><strong>${formatRangeLabel()}</strong><button class="period-arrow" data-action="period-next" aria-label="Periode berikutnya">${icon('fa-chevron-right')}</button></div><label class="field report-wallet"><span>Dompet</span><select class="control" id="reportWallet"><option value="all" ${reportWallet==='all'?'selected':''}>Semua dompet</option>${wallets.map(w=>`<option value="${w.name}" ${reportWallet===w.name?'selected':''}>${w.name}</option>`).join('')}</select></label><div class="metric-grid"><div class="card metric"><div class="metric-icon">${icon('fa-arrow-down')}</div><div class="metric-label">Pemasukan</div><div class="metric-value positive">${rp(income)}</div></div><div class="card metric out"><div class="metric-icon">${icon('fa-arrow-up')}</div><div class="metric-label">Pengeluaran</div><div class="metric-value negative">${rp(expense)}</div></div></div><section class="card"><div class="section-head"><h2 class="h2">Arus kas</h2></div><div class="sub">${reportWallet==='all'?'Semua dompet':reportWallet} · Pemasukan dan pengeluaran</div><div class="chart ${period==='Tahun'?'dense':''}" role="img" aria-label="Grafik periode ${formatRangeLabel()}. Pemasukan ${rp(income)}, pengeluaran ${rp(expense)}">${values.map(b=>`<div class="chart-group"><i class="bar" style="height:${peak?Math.max(3,b.income/peak*100):3}%" title="Pemasukan ${rp(b.income)}"></i><i class="bar exp" style="height:${peak?Math.max(3,b.expense/peak*100):3}%" title="Pengeluaran ${rp(b.expense)}"></i><span class="chart-label">${b.label}</span></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>Pemasukan</span><span><i class="dot exp"></i>Pengeluaran</span></div></section><section class="card"><div class="section-head"><h2 class="h2">Selisih</h2></div><div class="balance" style="font-size:23px">${signedRp(income-expense)}</div><div class="sub">Pemasukan dikurangi pengeluaran pada periode ini</div></section>${entries.length?'':'<section class="card empty"><div class="empty-icon">'+icon('fa-chart-column')+'</div><b>Belum ada transaksi pada periode ini</b><p>Angka dan grafik akan muncul setelah ada transaksi efektif.</p></section>'}<p class="sub">Data transaksi simulasi di prototipe.</p></div></main>${nav('report')}`}
function settings(){return `${renderTopBar()}<main><div class="heading"><div><div class="eyebrow">Atur pengalaman Arus</div><h1 class="h1">Pengaturan</h1></div></div><div class="stack"><div class="setting-group">DATA KEUANGAN</div><section class="card"><button class="setting-row" data-go="wallets"><span class="tile">${icon('fa-wallet')}</span><span class="wallet-info"><span class="row-title">Dompet</span><span class="row-meta">Kelola saldo dan nama dompet</span></span><span class="chevron">›</span></button><button class="setting-row" data-go="categories"><span class="tile">${icon('fa-tags')}</span><span class="wallet-info"><span class="row-title">Kategori</span><span class="row-meta">Atur kategori transaksi</span></span><span class="chevron">›</span></button></section><div class="setting-group">CADANGAN DATA</div><section class="card"><button class="setting-row" data-go="backup"><span class="tile">${icon('fa-shield-halved')}</span><span class="wallet-info"><span class="row-title">Backup & pulihkan</span><span class="row-meta">Simpan salinan data secara aman</span></span><span class="chevron">›</span></button></section><section class="card" style="background:var(--brand-soft);border:0"><b>Arus</b><div class="sub">Catat uang, pantau saldo, pahami arus keuangan.</div><div class="sub" style="margin-top:8px">Prototipe interaktif · data simulasi tersimpan lokal</div></section></div></main>${nav('settings')}`}
function walletsPage(){return `${renderTopBar('Dompet',true)}<main><div class="stack"><div class="card balance-card"><div class="eyebrow">Total saldo dompet</div><div class="balance">${rp(wallets.reduce((a,w)=>a+walletBalance(w),0))}</div><div class="balance-foot">Saldo contoh untuk prototipe</div></div><div class="section-head"><h2 class="h2">Semua dompet</h2><button class="link" data-go="wallet-form">＋ Tambah</button></div><section class="card wallet-list">${walletRows()}</section><button class="primary full" data-go="wallet-form">Tambah dompet</button></div></main>`}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function add(){const item=editingTxId===null?null:tx.find(x=>x.id===editingTxId);const categoryList=categoriesOf(formType).map(category=>category.name);if(item?.category&&!categoryList.includes(item.category))categoryList.unshift(item.category);const note=item?.note??(item&&item.title!==item.category&&item.type!=='transfer'?item.title:'');return `${renderTopBar(item?'Edit transaksi':'Catat transaksi',true)}<main><div class="stack"><div class="heading"><div><div class="eyebrow">${item?'Perbarui catatan':'Transaksi baru'}</div><h1 class="h1">${item?'Edit transaksi':'Catat uang'}</h1></div></div><section class="card form-card"><div class="type-tabs">${[['income','Masuk'],['expense','Keluar'],['transfer','Transfer']].map(([k,l])=>`<button class="${formType===k?'active':''}" data-type="${k}">${l}</button>`).join('')}</div><div><label class="eyebrow" for="amount" style="display:block;text-align:center">Nominal</label><input class="amount-input" id="amount" inputmode="numeric" placeholder="Rp0" value="${item?item.amount:''}" aria-label="Nominal rupiah"></div>${formType==='transfer'?`<div class="field"><label for="wallet">Dari dompet</label><select class="control" id="wallet">${wallets.map(w=>`<option ${item?.wallet===w.name?'selected':''}>${escapeHtml(w.name)}</option>`).join('')}</select></div><div class="field"><label for="toWallet">Ke dompet</label><select class="control" id="toWallet">${wallets.map((w,i)=>`<option ${item?.toWallet===w.name||(!item&&i===1)?'selected':''}>${escapeHtml(w.name)}</option>`).join('')}</select></div>`:`<div class="field"><label for="wallet">Dompet</label><select class="control" id="wallet">${wallets.map((w,i)=>`<option ${item?.wallet===w.name||(!item&&i===1)?'selected':''}>${escapeHtml(w.name)}</option>`).join('')}</select></div><div class="field"><label for="category">Kategori</label><select class="control" id="category">${categoryList.map((x,i)=>`<option ${item?.category===x||(!item&&i===0)?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></div>`}<div class="field"><label for="date">Tanggal</label><input class="control" id="date" type="date" value="${item?.date||dateKey(new Date())}"></div><div class="field"><label for="time">Jam</label><input class="control" id="time" type="time" value="${item?.time||new Date().toTimeString().slice(0,5)}"></div><div class="field"><label for="note">Catatan <span class="muted">(opsional)</span></label><textarea class="control" id="note" placeholder="Tulis catatan">${escapeHtml(note)}</textarea></div><button class="primary full" data-action="save-tx">${item?'Simpan perubahan':'Simpan transaksi'}</button></section><div class="sub">Simulasi prototipe. Tidak tersambung ke database aplikasi.</div></div></main>`}
function walletForm(){return `${renderTopBar('Tambah dompet',true)}<main><div class="stack"><div class="heading"><div><div class="eyebrow">Dompet baru</div><h1 class="h1">Tambah dompet</h1></div></div><section class="card form-card"><div class="field"><label for="walletName">Nama dompet</label><input class="control" id="walletName" placeholder="Contoh: Tunai"></div><div class="field"><label for="opening">Saldo awal</label><input class="control" id="opening" inputmode="numeric" placeholder="0"></div><button class="primary full" data-action="save-wallet">Simpan dompet</button></section></div></main>`}
function categoriesPage(){const list=categoriesOf(categoryType);return `${renderTopBar('Kategori',true)}<main><div class="heading"><div><div class="eyebrow">Atur label transaksi</div><h1 class="h1">Kategori</h1></div></div><div class="stack"><div class="pill-row"><button class="pill ${categoryType==='income'?'active':''}" data-action="category-income">Pemasukan</button><button class="pill ${categoryType==='expense'?'active':''}" data-action="category-expense">Pengeluaran</button></div><section class="card category-list">${list.length?list.map(category=>{const used=categoryUsage(category);return `<div class="category-row"><span class="tile">${icon(category.type==='income'?'fa-arrow-down':'fa-tags')}</span><span class="category-info"><span class="row-title">${escapeHtml(category.name)}</span><span class="row-meta">${used?`Dipakai ${used} transaksi`:'Belum dipakai'}</span></span><button class="icon-action" data-action="edit-category" data-category-id="${escapeHtml(category.id)}" aria-label="Ubah ${escapeHtml(category.name)}">${icon('fa-pen')}</button><button class="icon-action delete" data-action="request-category-delete" data-category-id="${escapeHtml(category.id)}" aria-label="Hapus ${escapeHtml(category.name)}">${icon('fa-trash-can')}</button></div>`}).join(''):`<div class="empty"><div class="empty-icon">${icon('fa-tags')}</div><b>Belum ada kategori</b><p>Tambahkan kategori agar transaksi lebih mudah dipahami.</p></div>`}</section><button class="primary full" data-action="add-category">${icon('fa-plus')} Tambah kategori ${categoryType==='income'?'pemasukan':'pengeluaran'}</button><div class="sub">Kategori yang sudah dipakai tidak bisa dihapus agar riwayat tetap utuh.</div></div></main>`}
function categoryForm(){const category=categories.find(item=>item.id===editingCategoryId);const type=category?.type||categoryFormType;return `${renderTopBar(category?'Ubah kategori':'Kategori baru',true)}<main><div class="stack"><div class="heading"><div><div class="eyebrow">${type==='income'?'Pemasukan':'Pengeluaran'}</div><h1 class="h1">${category?'Ubah kategori':'Kategori baru'}</h1></div></div><section class="card form-card"><div class="field"><label for="categoryName">Nama kategori</label><input class="control" id="categoryName" maxlength="32" placeholder="Contoh: Kesehatan" value="${escapeHtml(category?.name||'')}"></div><div class="sub">${category?'Mengubah nama akan memperbarui transaksi terkait.':'Pilih nama singkat yang mudah dikenali.'}</div><button class="primary full" data-action="save-category">${category?'Simpan perubahan':'Simpan kategori'}</button></section></div></main>`}
function backup(){return `${renderTopBar('Backup & pulihkan',true)}<main><div class="stack"><div class="heading"><div><div class="eyebrow">Cadangan data lokal</div><h1 class="h1">Backup & pulihkan</h1></div></div><section class="card"><div class="tile" style="margin-bottom:12px">${icon('fa-download')}</div><h2 class="h2">Backup data</h2><div class="sub">Buat salinan terenkripsi yang dapat disimpan di perangkat.</div><div style="height:16px"></div><button class="primary full" data-action="backup">Buat backup</button></section><section class="card"><div class="tile" style="margin-bottom:12px">${icon('fa-clock-rotate-left')}</div><h2 class="h2">Pulihkan data</h2><div class="sub">Pilih file backup Arus untuk memulihkan data.</div><div style="height:16px"></div><button class="secondary full" data-action="restore">Pilih file backup</button></section><p class="sub">Simulasi antarmuka. Proses backup terenkripsi belum dijalankan dalam prototipe.</p></div></main>`}
function updateWalletCarouselControl(){const carousel=document.querySelector('#wallet-carousel'),button=document.querySelector('.wallet-carousel-next');if(!carousel||!button)return;button.hidden=carousel.scrollWidth<=carousel.clientWidth+2||carousel.scrollLeft+carousel.clientWidth>=carousel.scrollWidth-2}
function render(){let view={home,transactions,report,settings,wallets:walletsPage,add,'wallet-form':walletForm,'transaction-detail':transactionDetail,categories:categoriesPage,'category-form':categoryForm,backup}[page]||home;const hasBottomNav=['home','transactions','report','settings'].includes(page);document.querySelector('#app').innerHTML=`<div class="shell ${hasBottomNav?'with-nav':''} ${page==='home'?'home-screen':''}">${view()}</div>`;updateWalletCarouselControl()}
function showSheet(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="dismiss"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="add-title"><div class="handle"></div><h3 id="add-title">Tambah transaksi</h3>${transactionActionButtons()}</section></div>`);document.querySelector('.sheet-action')?.focus()}
function showDeleteConfirmation(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="dismiss"><section class="sheet" role="alertdialog" aria-modal="true" aria-labelledby="delete-title"><div class="handle"></div><div class="delete-mark">${icon('fa-trash-can')}</div><h3 id="delete-title">Hapus transaksi ini?</h3><p class="sub">Transaksi akan dihapus dan saldo serta laporan akan dihitung ulang.</p><div class="delete-actions"><button class="secondary" data-action="cancel-delete">Batal</button><button class="danger-button" data-action="delete-tx">Hapus transaksi</button></div></section></div>`);document.querySelector('[data-action="cancel-delete"]')?.focus()}
function showCategoryDeleteConfirmation(name){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="dismiss"><section class="sheet" role="alertdialog" aria-modal="true" aria-labelledby="delete-category-title"><div class="handle"></div><div class="delete-mark">${icon('fa-trash-can')}</div><h3 id="delete-category-title">Hapus kategori?</h3><p class="sub">Kategori “${escapeHtml(name)}” akan dihapus. Transaksi lama tetap tersimpan.</p><div class="delete-actions"><button class="secondary" data-action="cancel-category-delete">Batal</button><button class="danger-button" data-action="delete-category">Hapus kategori</button></div></section></div>`);document.querySelector('[data-action="cancel-category-delete"]')?.focus()}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;let pos=e.target.selectionStart;render();let el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='reportWallet'){reportWallet=e.target.value;render()}else if(e.target.id==='transactionWallet'){transactionWalletFilter=e.target.value;render()}});
document.addEventListener('keydown',e=>{const modal=document.querySelector('.modal-backdrop');if(!modal)return;if(e.key==='Escape'){modal.remove();return}if(e.key==='Tab'){const focusable=[...modal.querySelectorAll('button:not([disabled]),a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',e=>{
  const go=e.target.closest('[data-go]');
  if(go){setPage(go.dataset.go);return}
  const typeButton=e.target.closest('[data-type]');
  if(typeButton){formType=typeButton.dataset.type;render();return}
  const periodButton=e.target.closest('[data-period]');
  if(periodButton){period=periodButton.dataset.period;render();return}
  const dateFilterButton=e.target.closest('[data-action="date-filter"]');
  if(dateFilterButton){transactionDateFilter=dateFilterButton.dataset.dateFilter;render();return}
  const button=e.target.closest('[data-action]');
  if(!button)return;
  const action=button.dataset.action;
  if(action==='toggle-balance'){showBalance=!showBalance;render()}
  else if(action==='select-cashflow-day'){selectedCashflowDate=button.dataset.date;document.querySelectorAll('.cashflow-day').forEach(item=>{const selected=item===button;item.classList.toggle('selected',selected);item.setAttribute('aria-pressed',String(selected))});const detail=document.querySelector('#cashflow-detail');const dayData=button.dataset;const label=new Date(`${dayData.date}T12:00:00`).toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long'});detail.replaceChildren();const title=document.createElement('strong');title.textContent=label;const inRow=document.createElement('span');const inDot=document.createElement('i');inDot.className='cashflow-dot';const inLabel=document.createTextNode(`Masuk ${rp(Number(dayData.income))}`);inRow.append(inDot,inLabel);const outRow=document.createElement('span');const outDot=document.createElement('i');outDot.className='cashflow-dot expense';const outLabel=document.createTextNode(`Keluar ${rp(Number(dayData.expense))}`);outRow.append(outDot,outLabel);detail.append(title,inRow,outRow);detail.hidden=false}
  else if(action==='wallet-next'){const carousel=document.querySelector('#wallet-carousel');carousel?.scrollBy({left:carousel.clientWidth*0.72,behavior:'smooth'})}
  else if(action==='add'||action==='open-sheet'){showSheet()}
  else if(action==='dismiss'&&e.target===button){if(pendingCategoryId!==null)pendingCategoryId=null;button.remove()}
  else if(action.startsWith('new-')){document.querySelector('.modal-backdrop')?.remove();editingTxId=null;formType=action.slice(4);setPage('add')}
  else if(action==='open-detail'){selectedTxId=Number(button.dataset.txId);editingTxId=null;setPage('transaction-detail')}
  else if(action==='edit-tx'){const item=tx.find(x=>x.id===selectedTxId);if(!item){toast('Transaksi tidak ditemukan');return}editingTxId=item.id;formType=item.type;setPage('add')}
  else if(action==='confirm-delete'){showDeleteConfirmation()}
  else if(action==='cancel-delete'){document.querySelector('.modal-backdrop')?.remove()}
  else if(action==='delete-tx'){if(selectedTxId===null)return;tx=tx.filter(x=>x.id!==selectedTxId);writeStorage('arus-demo-tx',JSON.stringify(tx));document.querySelector('.modal-backdrop')?.remove();selectedTxId=null;editingTxId=null;toast('Transaksi dihapus');setPage('transactions')}
  else if(action==='category-income'||action==='category-expense'){categoryType=action==='category-income'?'income':'expense';render()}
  else if(action==='add-category'){editingCategoryId=null;categoryFormType=categoryType;setPage('category-form')}
  else if(action==='edit-category'){editingCategoryId=button.dataset.categoryId;const item=categories.find(category=>category.id===editingCategoryId);if(!item){toast('Kategori tidak ditemukan');return}categoryFormType=item.type;setPage('category-form')}
  else if(action==='save-category'){
    const name=document.querySelector('#categoryName').value.trim();
    if(!name){toast('Isi nama kategori dulu');return}
    const duplicate=categories.some(category=>category.type===categoryFormType&&category.name.toLocaleLowerCase()===name.toLocaleLowerCase()&&category.id!==editingCategoryId);
    if(duplicate){toast('Kategori dengan nama itu sudah ada');return}
    if(editingCategoryId!==null){const existing=categories.find(category=>category.id===editingCategoryId);if(!existing){toast('Kategori tidak ditemukan');return}const oldName=existing.name;categories=categories.map(category=>category.id===editingCategoryId?{...category,name}:category);tx=tx.map(item=>item.type===categoryFormType&&item.category===oldName?{...item,category:name,title:!item.note||item.title===oldName?name:item.title}:item);writeStorage('arus-demo-tx',JSON.stringify(tx));toast('Kategori dan transaksi terkait diperbarui')}
    else{categories.push({id:`category-${Date.now()}`,type:categoryFormType,name});toast('Kategori ditambahkan')}
    writeStorage('arus-demo-categories',JSON.stringify(categories));categoryType=categoryFormType;editingCategoryId=null;setPage('categories')
  }
  else if(action==='request-category-delete'){const item=categories.find(category=>category.id===button.dataset.categoryId);if(!item){toast('Kategori tidak ditemukan');return}if(categoryUsage(item)>0){toast('Kategori yang sudah dipakai tidak bisa dihapus');return}pendingCategoryId=item.id;showCategoryDeleteConfirmation(item.name)}
  else if(action==='cancel-category-delete'){pendingCategoryId=null;document.querySelector('.modal-backdrop')?.remove()}
  else if(action==='delete-category'){const item=categories.find(category=>category.id===pendingCategoryId);if(!item){pendingCategoryId=null;document.querySelector('.modal-backdrop')?.remove();return}if(categoryUsage(item)>0){toast('Kategori yang sudah dipakai tidak bisa dihapus')}else{categories=categories.filter(category=>category.id!==item.id);writeStorage('arus-demo-categories',JSON.stringify(categories));toast('Kategori dihapus')}pendingCategoryId=null;document.querySelector('.modal-backdrop')?.remove();setPage('categories')}
  else if(action==='save-tx'){
    const amount=Number((document.querySelector('#amount').value||'').replace(/\D/g,''));
    const effectiveDate=document.querySelector('#date').value;
    if(!amount){toast('Masukkan nominal lebih dari Rp0');return}
    if(!effectiveDate){toast('Pilih tanggal transaksi');return}
    const effectiveTime=document.querySelector('#time')?.value;
    if(!effectiveTime){toast('Pilih jam transaksi');return}
    const type=formType,from=document.querySelector('#wallet')?.value;
    if(!from){toast('Pilih dompet transaksi');return}
    if(type==='transfer'){
      const to=document.querySelector('#toWallet')?.value;
      if(!from||!to){toast('Pilih dompet asal dan tujuan');return}
      if(from===to){toast('Pilih dompet tujuan yang berbeda');return}
      const note=document.querySelector('#note').value.trim();
      const id=editingTxId??Date.now();
      const entry={id,title:note||'Transfer',note,wallet:from,toWallet:to,amount,type,date:effectiveDate,time:effectiveTime};
      if(editingTxId!==null)tx=tx.map(x=>x.id===editingTxId?entry:x);else tx.unshift(entry);
      writeStorage('arus-demo-tx',JSON.stringify(tx));selectedTxId=id;editingTxId=null;toast('Transfer disimpan');setPage('transaction-detail');return
    }
    const category=document.querySelector('#category').value;
    const note=document.querySelector('#note').value.trim();
    const id=editingTxId??Date.now();
    const entry={id,title:note||category,note,category,wallet:from,amount,type,date:effectiveDate,time:effectiveTime};
    if(editingTxId!==null)tx=tx.map(x=>x.id===editingTxId?entry:x);else tx.unshift(entry);
    writeStorage('arus-demo-tx',JSON.stringify(tx));
    if(editingTxId!==null){selectedTxId=id;editingTxId=null;toast('Perubahan disimpan');setPage('transaction-detail')}
    else{toast('Transaksi tersimpan di prototipe');setPage('transactions')}
  }
  else if(action==='save-wallet'){const name=document.querySelector('#walletName').value.trim();const amount=Number((document.querySelector('#opening').value||'').replace(/\D/g,''));if(!name){toast('Isi nama dompet dulu');return}wallets.push({name,icon:'◉',openingBalance:amount});writeStorage('arus-demo-wallets',JSON.stringify(wallets));toast('Dompet ditambahkan');setPage('wallets')}
  else if(action==='filter-income'||action==='filter-expense'||action==='filter-all'){typeFilter=action==='filter-income'?'income':action==='filter-expense'?'expense':'all';render()}
  else if(action==='backup'){toast('Simulasi: alur backup belum terhubung')}
  else if(action==='restore'){toast('Simulasi: pemilih file belum terhubung')}
  else if(action==='period-prev'||action==='period-next'){shiftReport(action==='period-prev'?-1:1);render()}
});
document.addEventListener('scroll',e=>{if(e.target?.id==='wallet-carousel')updateWalletCarouselControl()},true);
window.addEventListener('resize',updateWalletCarouselControl);
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render()});render();
